HAND_LIMIT = 10

switchWindow(TitleWindow:new())

function TIC()
	doSync()
	window:windowTick()
end

-- in game properties
seed = 0
ascension = 0
mainRandom = nil
player = nil
floor = 1
gold = 0
deck = {}
potions = {Slot,Slot,Slot}
relics = {}
maxEnergy = 3
rubyKeyObtained = false
emeraldKeyObtained = false
sapphireKeyObtained = false
relicPools = {common={},uncommon={},rare={},shop={},boss={}}

-- in act properties
act = nil
stsMap = {}
boss = nil -- TODO use bossEncounter
monsterEncounters = {}
eliteEncounters = {}
bossEncounter = nil
nextMonsterEncounterIndex = 1
nextEliteEncounterIndex = 1
playerPath = {}
currentRoomX = 0
currentRoomY = 0
room = {}
roomType = nil

local availableBosses = {
	{'Slime','Hexaghost','Guardian'},
	{'Champ','Collector','Automation'},
	{'Donu','TimeEater','Awakened'},
	{'Heart'}
}

function startGame(character,ascensionLevel)
	mainRandom = Random:new(math.floor(tstamp()*2))
	seed = mainRandom:randRaw()
	ascension = ascensionLevel or 0
	player = _G[character]:new()
	if ascension >= 14 then
		player:decreaseMaxHp(player:getAscensionMaxHPLoss())
	end
	if ascension >= 6 then
		player.hp = math.floor(player.maxHp*0.9+0.5)
	end
	relicPools = generateRelicPools(makeRand(0))
	floor = 0
	gold = 99
	deck = player:getStartDeck()
	if ascension >= 10 then
		table.insert(deck,1,AscendersBane:new())
	end
	relics = player:getStartRelics()
	potions = {Slot,Slot,Slot}
	if ascension >= 11 then
		potions[3] = nil
	end
	maxEnergy = 3
	effects = {}
	pendingEffects = {}
	rubyKeyObtained = false
	emeraldKeyObtained = false
	sapphireKeyObtained = false
	currentEvent = NeowEvent:new(makeRand(1))
	cursorOnTopBar = false
	startAct(1)
	switchWindow(GameWindow:new())
end

function startAct(actId)
	act = acts[actId]
	local mapRandom = makeRand(actId)
	stsMap = generateMap(mapRandom,7,15,6)
	boss = availableBosses[actId][mapRandom:randInt(#availableBosses[actId])]
	monsterEncounters,eliteEncounters,bossEncounter = act:generateEncounters(mapRandom)
	nextMonsterEncounterIndex = 1
	nextEliteEncounterIndex = 1
	playerPath = {}
	currentRoomX = 0
	currentRoomY = 0
	room = {id=0,x=0,y=0,previous={},next={},type=nil,completed=false}
	for _, nextRoom in ipairs(stsMap[1]) do
		table.insert(room.next,nextRoom)
	end
	roomType = 'event'
	resetRewardGenerator()
	act:playEntryEffect()
end

function completeRoom()
	if room.completed then
		return
	end
	room.completed = true
	mapScreenAvailableSelections = {}
	for _, nextRoom in ipairs(room.next) do
		table.insert(mapScreenAvailableSelections,nextRoom.x)
	end
	mapScreenX = 0
	currentRoomY = currentRoomY + 1
	mapScreenY = currentRoomY
	if currentRoomY > 1 then
		table.insert(playerPath,currentRoomX)
	end
	mapScreenSelectionMode = true
end

function enterRoom(x)
	mapScreenSelectionMode = false
	currentRoomX = x
	floor = floor + 1

	nextRooms = room.next
	room = nil
	for _, nextRoom in ipairs(nextRooms) do
		if nextRoom.x == currentRoomX then
			room = nextRoom
			break
		end
	end
	if room == nil then
		room = map[currentRoomY][currentRoomX]
	end

	if room.type == 'monster' then
		roomType = 'combat'
		startCombat(monsterEncounters[nextMonsterEncounterIndex])
		nextMonsterEncounterIndex = nextMonsterEncounterIndex + 1
	elseif room.type == 'elite' then
		roomType = 'combat'
		startCombat(eliteEncounters[nextEliteEncounterIndex])
		nextEliteEncounterIndex = nextEliteEncounterIndex + 1
	elseif room.type == 'boss' then
		roomType = 'combat'
		startCombat(bossEncounter)
	elseif room.type == 'rest' then
		roomType = 'event'
		currentEvent = CampfireEvent:new()
		closeChildWindows()
	elseif room.type == 'treasure' then
		roomType = 'event'
		currentEvent = TreasureEvent:new()
		closeChildWindows()
	else
		roomType = 'event'
		closeChildWindows()
		-- TODO currentEvent = generateEvent()
	end
end

-- main

queueSync(32,1)
startGame('Ironclad',20)
--roomType = 'combat'
--startCombat(GremlinGangEncounter)
--currentEvent = TreasureEvent:new()
window:onOpen()

